package vn.smartfarm.iot.control;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
import vn.smartfarm.iot.nodes.*;import vn.smartfarm.iot.irrigation.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.irrigation.queue-handoff-enabled=true","smartfarm.irrigation-queue.scheduling-enabled=false","smartfarm.control.enabled=true","smartfarm.control.pump-fencing-enabled=true","smartfarm.control.circuit-route-required=true","smartfarm.irrigation.circuit-demo-enabled=true","smartfarm.irrigation.session-enabled=true","smartfarm.irrigation.water-stop-enabled=true","smartfarm.irrigation.water-stop-poll-ms=3600000","smartfarm.irrigation.rain-stop-enabled=true","smartfarm.irrigation.rain-stop-poll-ms=3600000"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class QueueSessionHandoffTest {
 @Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired CircuitWaterGate gate;@Autowired IrrigationQueue queue;@Autowired IrrigationQueueHandoff handoff;@Autowired ZoneRainGate weatherGate;@Autowired NodeInventory nodes;@Autowired TelemetryRouter router;
 @Autowired PumpService pump;@Autowired PumpCommandFencing fencing;@Autowired PumpCircuitProof proof;@Autowired CircuitValveControl valves;@Autowired IrrigationCircuits circuits;@Autowired IrrigationSession sessions;@Autowired MockMvc mvc;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
 @MockitoBean CommandTransport transport;@MockitoBean CircuitValveTransport valveTransport;
 UUID boot=UUID.fromString("83000000-0000-4000-8000-000000000001"),vboot=UUID.fromString("83000000-0000-4000-8000-000000000002");PumpCircuitRoute route;
 @BeforeEach void setup()throws Exception{
  cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");reset(transport,valveTransport);when(transport.controlConnected()).thenReturn(true);when(valveTransport.circuitValveConnected(anyString())).thenReturn(true);
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('WGSOIL','Soil','AREA001','SOIL',2),('WGWATER','Water','AREA001','WATER',2)");
  for(int i=1;i<=3;i++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('WGSOIL',?,'SOIL_MOISTURE','%')","SOIL"+i);
  jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('WGWATER','LOW','WATER_PRESENT','boolean'),('WGWATER','FLOW','FLOW_RATE','L/min')");
  jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES('WGZONE','Zone','AREA001','WGSOIL','SIMULATOR',30,35)");
  jdbc.update("INSERT INTO irrigation_circuit(circuit_id,name,zone_id,zone_revision,controller_id,valve_id,pump_id,water_node_id,low_channel_id,flow_channel_id,expected_source) VALUES('WGC','Circuit','WGZONE',1,'IRRIGATION75','VALVE75','PUMP01','WGWATER','LOW','FLOW','SIMULATOR')");
  for(int i=1;i<=3;i++)jdbc.update("INSERT INTO irrigation_zone_channel(zone_id,node_id,channel_id,position) VALUES('WGZONE','WGSOIL',?,?)","SOIL"+i,i-1);
  route=PumpCircuitRoute.from(circuits.find("WGC"));pumpStatus(1,0,"OFF");valveStatus(1,0,"CLOSED");
 }
 @AfterEach void after(){cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");}
 void cleanup(){jdbc.update("DELETE FROM irrigation_queue_handoff WHERE request_id IN(SELECT request_id FROM irrigation_queue_request WHERE zone_id='WGZONE')");jdbc.update("DELETE FROM irrigation_queue_request WHERE zone_id='WGZONE'");jdbc.update("DELETE FROM irrigation_water_stop WHERE circuit_id='WGC'");jdbc.update("DELETE FROM irrigation_weather_stop WHERE zone_id='WGZONE'");jdbc.update("DELETE FROM irrigation_session_action WHERE session_id IN(SELECT session_id FROM irrigation_session WHERE circuit_id='WGC')");jdbc.update("DELETE FROM irrigation_session WHERE circuit_id='WGC'");for(String t:List.of("circuit_demo_command","circuit_demo_status","circuit_demo_boot","circuit_demo_gate"))jdbc.update("DELETE FROM "+t+" WHERE valve_id='VALVE75'");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id='WGC'");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id='WGZONE'");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('WGSOIL','WGWATER','WGWEATHER')");jdbc.update("DELETE FROM sensor_area WHERE id='WGAREA'");}
 void pumpStatus(long seq,long ordinal,String state)throws Exception {var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",boot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("connection","ONLINE").put("reportedState",state).put("safetyLockout",false).put("stateReason",state.equals("ON")?"COMMAND_ON":"COMMAND_OFF");p.putObject("commandFence").put("version",1).put("lastOrdinal",ordinal).put("restartRequired",false);p.putObject("valveInterlock").put("version",1).put("enabled",true).put("dataSource","SIMULATOR").put("state","OPEN").putNull("fault").set("route",mapper.valueToTree(route));pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(p));}
 ObjectNode valvePacket(long seq,long ordinal,String state){var c=circuits.find("WGC");var p=mapper.createObjectNode().put("schemaVersion",1).put("controlProfile",CircuitValveControl.PROFILE).put("controllerId",c.controllerId()).put("actuatorId",c.valveId()).put("circuitId",c.circuitId()).put("circuitRevision",1).put("zoneId",c.zoneId()).put("zoneRevision",1).put("bootId",vboot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("dataSource","SIMULATOR").put("feedbackState",state).put("gpioState",state).put("reason",state.equals("OPEN")?"COMMAND_OPEN":"COMMAND_CLOSE").put("demoEnabled",true).put("lastOrdinal",ordinal);p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state",state).putNull("fault");return p;}
 void valveStatus(long seq,long ordinal,String state)throws Exception {valves.receive(CircuitValveControl.topic("VALVE75","status"),mapper.writeValueAsBytes(valvePacket(seq,ordinal,state)),false);}
 void open()throws Exception {var c=valves.create("WGC",new CircuitValveControl.Request(UUID.randomUUID(),"OPEN",30,vboot,1,1,Instant.now()));var p=valvePacket(2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode");valves.receive(CircuitValveControl.topic("VALVE75","ack"),mapper.writeValueAsBytes(p),false);valveStatus(3,c.ordinal(),"OPEN");}
 PumpCommandFencing.HttpIntent intent(String action){var c=fencing.view().intent();return new PumpCommandFencing.HttpIntent(UUID.randomUUID(),action,action.equals("ON")?5:null,action.equals("OFF")?null:boot,c.revision(),c.asOf(),action.equals("OFF")?null:route);}
 CircuitWaterGate.Request request(int revision,boolean enabled){return new CircuitWaterGate.Request(revision,1,null,enabled);}
 void enable(){gate.save("WGC",request(0,true));}
 ObjectNode packet(long seq,Boolean present,Instant at)throws Exception {var p=(ObjectNode)mapper.readTree(getClass().getResourceAsStream("/water-firmware-packet.json"));p.put("deviceId","WGWATER").put("sequence",seq).put("timestamp",at.toString());p.withArray("readings").remove(1);var r=(ObjectNode)p.path("readings").get(0);if(present==null)r.put("quality","SENSOR_FAULT").putNull("value");else r.put("value",present);return p;}
 void water(long seq,Boolean present,Instant at)throws Exception {router.store("smartfarm/FARM001/WGWATER/telemetry",mapper.writeValueAsBytes(packet(seq,present,at)));}
 IrrigationQueue.Item add(int seconds){return queue.enqueue(mapper.createObjectNode().put("requestId",UUID.randomUUID().toString()).put("zoneId","WGZONE").put("zoneRevision",1).put("circuitId","WGC").put("circuitRevision",1).put("durationSeconds",seconds).put("requestedAt",Instant.now().toString()));}
 IrrigationQueueHandoff.Request request(IrrigationQueue.Item item){var v=handoff.snapshot(item.requestId());return new IrrigationQueueHandoff.Request(v.queueRevision(),new IrrigationSession.Start(UUID.randomUUID(),1,1,boot,vboot,item.durationSeconds(),v.asOf()));}
 int prepared(){return jdbc.queryForObject("SELECT count(*) FROM irrigation_queue_handoff",Integer.class);}
 void noDispatch()throws Exception{verify(transport,never()).publishCommand(any());verify(valveTransport,never()).publishCircuitValve(anyString(),any());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM pump_command",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM irrigation_session_action",Integer.class));}
 @Test void explicitHeadHandoffCreatesPreparedOnlyAndKeepsNextWaiting()throws Exception{var a=add(5);var b=add(5);var v=handoff.snapshot(a.requestId());assertTrue(v.canPrepare());assertEquals("READY",v.reason());var input=request(a);var result=handoff.prepare(a.requestId(),input);assertEquals("PREPARED",result.session().phase());assertEquals(input.session().sessionId(),result.session().sessionId());assertEquals("HANDED_OFF",queue.lookup(a.requestId()).state());assertEquals("OPERATOR_SESSION_PREPARED",queue.lookup(a.requestId()).reason());assertEquals(a.circuitSnapshot(),queue.lookup(a.requestId()).circuitSnapshot());assertEquals(a.expiresAt(),queue.lookup(a.requestId()).expiresAt());assertEquals("QUEUED",queue.lookup(b.requestId()).state());assertEquals(1,prepared());assertEquals("SESSION_SESSION_ACTIVE",handoff.snapshot(b.requestId()).reason());noDispatch();}
 @Test void defaultFlagDoesNotPrepare()throws Exception{var item=add(5);var disabled=new IrrigationQueueHandoff(jdbc,mapper,queue,sessions,false);assertEquals("PROFILE_DISABLED",disabled.snapshot(item.requestId()).reason());assertThrows(Exception.class,()->disabled.prepare(item.requestId(),request(item)));assertEquals(0,prepared());noDispatch();}
 @Test void onlyFirstReviewedQueueItemCanTransfer()throws Exception{var a=add(5);var b=add(5);assertEquals("NOT_FIFO_HEAD",handoff.snapshot(b.requestId()).reason());assertThrows(Exception.class,()->handoff.prepare(b.requestId(),request(b)));assertEquals("QUEUED",queue.lookup(a.requestId()).state());assertEquals(0,prepared());noDispatch();}
 @Test void staleQueueRevisionRejectsBeforeSessionCreation()throws Exception{var a=add(5);var input=request(a);add(5);assertThrows(Exception.class,()->handoff.prepare(a.requestId(),input));assertEquals(0,prepared());assertNull(sessions.snapshot("WGC").active());noDispatch();}
 @Test void changedBootAndDurationAreNeverRetargeted()throws Exception {var a=add(5);var input=request(a);var s=input.session();assertThrows(Exception.class,()->handoff.prepare(a.requestId(),new IrrigationQueueHandoff.Request(input.queueRevision(),new IrrigationSession.Start(s.sessionId(),1,1,boot,vboot,4,s.reviewedAt()))));pumpStatus(2,0,"OFF");jdbc.update("UPDATE pump_status SET boot_id=? WHERE singleton=1",UUID.randomUUID());assertThrows(Exception.class,()->handoff.prepare(a.requestId(),input));assertEquals(0,prepared());noDispatch();}
 @Test void longPreviewCannotSilentlyBecomeShortSession()throws Exception{var a=add(20);assertEquals("DURATION_TOO_LONG",handoff.snapshot(a.requestId()).reason());assertThrows(Exception.class,()->handoff.prepare(a.requestId(),request(a)));assertEquals(20,queue.lookup(a.requestId()).durationSeconds());assertEquals(0,prepared());noDispatch();}
 @Test void expiredRequestAndChangedMappingCannotTransfer()throws Exception{var a=add(5);var input=request(a);jdbc.update("UPDATE irrigation_queue_request SET enqueued_at=CURRENT_TIMESTAMP-INTERVAL '301 seconds',expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE request_id=?",a.requestId());assertEquals("EXPIRED",handoff.snapshot(a.requestId()).reason());assertThrows(Exception.class,()->handoff.prepare(a.requestId(),input));noDispatch();}
 @Test void changedConfigurationCannotTransfer()throws Exception{var a=add(5);var input=request(a);jdbc.update("UPDATE irrigation_circuit SET revision=2 WHERE circuit_id='WGC'");assertEquals("CONFIG_CHANGED",handoff.snapshot(a.requestId()).reason());assertThrows(Exception.class,()->handoff.prepare(a.requestId(),input));assertEquals(0,prepared());noDispatch();}
 @Test void zoneSnapshotChangeWithoutRevisionIsDetected()throws Exception{var a=add(5);var input=request(a);jdbc.update("UPDATE irrigation_zone SET name='Changed outside normal API' WHERE zone_id='WGZONE'");assertEquals("CONFIG_CHANGED",handoff.snapshot(a.requestId()).reason());assertThrows(Exception.class,()->handoff.prepare(a.requestId(),input));noDispatch();}
 @Test void existingRehearsalMustEndBeforeHandoff()throws Exception{var a=add(5);var b=add(5);queue.rehearse(a.requestId(),queue.snapshot().revision());assertEquals("REHEARSAL_ACTIVE",handoff.snapshot(b.requestId()).reason());assertThrows(Exception.class,()->handoff.prepare(b.requestId(),request(b)));noDispatch();}
 @Test void lowGateAndMissingDeviceProofStillBlockPreparation()throws Exception{gate.save("WGC",new CircuitWaterGate.Request(0,1,null,true));var a=add(5);assertEquals("SESSION_WATER_MISSING",handoff.snapshot(a.requestId()).reason());assertThrows(Exception.class,()->handoff.prepare(a.requestId(),request(a)));assertEquals(0,prepared());noDispatch();}
 @Test void flowGraceMustFitQueuedDuration()throws Exception{jdbc.update("INSERT INTO circuit_flow_guard(circuit_id,circuit_revision,enabled,minimum_lpm,grace_seconds,revision) VALUES('WGC',1,true,2,5,1)");var a=add(5);assertEquals("FLOW_GRACE_TOO_LONG",handoff.snapshot(a.requestId()).reason());assertThrows(Exception.class,()->handoff.prepare(a.requestId(),request(a)));noDispatch();}
 @Test void duplicateAfterRestartAndExpiryReturnsSameCurrentSession()throws Exception{var a=add(5);var input=request(a);var first=handoff.prepare(a.requestId(),input);sessions.interruptOnStartup();queue.interruptOnStartup();var again=handoff.prepare(a.requestId(),input);assertEquals(first.session().sessionId(),again.session().sessionId());assertEquals("RECOVERY_REQUIRED",again.session().phase());assertEquals(first.preparedAt(),again.preparedAt());assertEquals(1,prepared());assertEquals("HANDED_OFF",handoff.snapshot(a.requestId()).reason());noDispatch();}
 @Test void changedDuplicateNeverCreatesAnotherSession()throws Exception{var a=add(5);var input=request(a);handoff.prepare(a.requestId(),input);var s=input.session();assertThrows(Exception.class,()->handoff.prepare(a.requestId(),new IrrigationQueueHandoff.Request(input.queueRevision(),new IrrigationSession.Start(UUID.randomUUID(),1,1,boot,vboot,5,s.reviewedAt()))));assertEquals(1,prepared());noDispatch();}
 @Test void existingDirectSessionCannotBeAdopted()throws Exception{var a=add(5);var input=request(a);sessions.start("WGC",input.session());assertThrows(Exception.class,()->handoff.prepare(a.requestId(),input));assertEquals(0,prepared());assertEquals("QUEUED",queue.lookup(a.requestId()).state());noDispatch();}
 @Test void terminalQueueActionsDoNotCancelOrRehearsePreparedSession()throws Exception{var a=add(5);var result=handoff.prepare(a.requestId(),request(a));long revision=queue.snapshot().revision();assertEquals("HANDED_OFF",queue.cancel(a.requestId(),revision).state());assertEquals("HANDED_OFF",queue.rehearse(a.requestId(),revision).state());assertEquals(revision,queue.snapshot().revision());assertEquals(result.session(),sessions.find("WGC",result.session().sessionId()));noDispatch();}
 @Test void concurrentDuplicatePreparationHasOneLinkAndSession()throws Exception {var a=add(5);var input=request(a);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var results=pool.invokeAll(List.<java.util.concurrent.Callable<IrrigationQueueHandoff.Receipt>>of(()->handoff.prepare(a.requestId(),input),()->handoff.prepare(a.requestId(),input)));assertEquals(results.get(0).get().session().sessionId(),results.get(1).get().session().sessionId());}assertEquals(1,prepared());noDispatch();}
 @Test void cancellationRaceDoesNotCreateTwoOutcomes()throws Exception {var a=add(5);var input=request(a);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){for(var f:pool.invokeAll(List.<java.util.concurrent.Callable<Void>>of(()->{try{handoff.prepare(a.requestId(),input);}catch(org.springframework.web.server.ResponseStatusException ignored){}return null;},()->{try{queue.cancel(a.requestId(),input.queueRevision());}catch(org.springframework.web.server.ResponseStatusException ignored){}return null;})))f.get();}var state=queue.lookup(a.requestId()).state();assertTrue(Set.of("HANDED_OFF","CANCELLED").contains(state));assertEquals(state.equals("HANDED_OFF")?1:0,prepared());noDispatch();}
 @Test void failedSessionStartRollsBackPreparationAndManualHold()throws Exception{var a=add(5);var input=request(a);String old=jdbc.queryForObject("SELECT row_to_json(w)::text FROM watering_rule w",String.class);var spy=spy(org.springframework.test.util.AopTestUtils.<IrrigationSession>getUltimateTargetObject(sessions));doAnswer(call->{call.callRealMethod();throw new IllegalStateException("Synthetic rollback");}).when(spy).start(anyString(),any());var local=new IrrigationQueueHandoff(jdbc,mapper,queue,spy,true);assertThrows(Exception.class,()->new org.springframework.transaction.support.TransactionTemplate(manager).execute(t->local.prepare(a.requestId(),input)));assertEquals("QUEUED",queue.lookup(a.requestId()).state());assertEquals(0,prepared());assertNull(sessions.snapshot("WGC").active());assertEquals(old,jdbc.queryForObject("SELECT row_to_json(w)::text FROM watering_rule w",String.class));noDispatch();}
 @Test void controllerGetDoesNotPrepareAndPostDefinitionIsReadBack()throws Exception {var a=add(5);mvc.perform(get("/api/v1/irrigation-queue/requests/"+a.requestId()+"/session-handoff")).andExpect(status().isOk()).andExpect(jsonPath("$.canPrepare").value(true));assertEquals(0,prepared());var input=request(a);mvc.perform(post("/api/v1/irrigation-queue/requests/"+a.requestId()+"/session-handoff").contentType("application/json").content(mapper.writeValueAsString(input))).andExpect(status().isCreated()).andExpect(jsonPath("$.session.phase").value("PREPARED"));mvc.perform(get("/api/v1/irrigation-queue/requests/"+a.requestId()+"/session-handoff")).andExpect(status().isOk()).andExpect(jsonPath("$.receipt.definition.session.sessionId").value(input.session().sessionId().toString()));noDispatch();}
}
